commands.command:
sudo mkdir -p /usr/share/nginx/html-rotate
echo "certificate-rotation ok on $(hostname)" | sudo tee /usr/share/nginx/html-rotate/index.html >/dev/null
cat <<'EOF' | sudo tee /etc/nginx/conf.d/tls-rotate.conf >/dev/null
server {
    listen 8443 ssl;
    server_name _;

    ssl_certificate     /etc/pki/tls-rotate/live/fullchain.pem;
    ssl_certificate_key /etc/pki/tls-rotate/live/privkey.pem;

    location / {
        root /usr/share/nginx/html-rotate;
        index index.html;
    }
}
EOF
cat /etc/nginx/conf.d/tls-rotate.conf

